# Events that threw a Central Code away, and the Retired Code reason for each.
# Self-contained on purpose: a migration must not import app models that change.
_EVENT_REASON = {"code_reissued": "reissued", "code_overridden": "overridden",
                 "code_burned": "rejected"}
_CODE = re.compile(r"(?<!\d)\d{11}(?!\d)")


def _thrown_away_code(action: str, detail: str | None) -> str | None:
    """The retired code in an event's text: "<old> -> <new>", or the code in a
    code_burned message. None if the text holds no 11-digit code (early overrides
    accepted any text)."""
    if not detail:
        return None
    if action == "code_burned":
        m = _CODE.search(detail)
        return m.group(0) if m else None
    old = detail.split(" -> ", 1)[0].strip()
    return old if _CODE.fullmatch(old) else None


def _backfill_from_events() -> None:
    """Retire every code the event history says was thrown away.

    One row per code: a code_burned event (rejected after approval) wins, since
    that is what finally threw the number away; otherwise the first event.
    Codes still carried by a live (not rejected) request are skipped: they are in
    use, not thrown away. A request rejected after approval keeps its code, and
    that code is retired.
    """
    bind = op.get_bind()
    in_use = {row[0] for row in bind.execute(sa.text(
        "SELECT generated_code FROM item_requests "
        "WHERE generated_code IS NOT NULL AND status != 'rejected'"))}
    events = bind.execute(sa.text(
        "SELECT request_id, action, detail, actor, at FROM request_events "
        "WHERE action IN ('code_reissued', 'code_overridden', 'code_burned') "
        "ORDER BY at, id"))
    retired = sa.table("retired_codes", sa.column("code"), sa.column("request_id"),
                       sa.column("reason"), sa.column("actor"), sa.column("at"))
    chosen: dict[str, dict] = {}
    still_in_use, not_a_code = set(), 0
    for request_id, action, detail, actor, at in events:
        code = _thrown_away_code(action, detail)
        if code is None:
            not_a_code += 1
            continue
        if code in in_use:
            still_in_use.add(code)
            continue
        if code in chosen and not (action == "code_burned"
                                   and chosen[code]["reason"] != "rejected"):
            continue
        chosen[code] = {"code": code, "request_id": request_id,
                        "reason": _EVENT_REASON[action], "actor": actor, "at": at}
    rows = list(chosen.values())
    if rows:
        op.bulk_insert(retired, rows)
    print(f"retired_codes backfill: {len(rows)} added, {len(still_in_use)} skipped "
          f"(still in use), {not_a_code} skipped (no 11-digit code in the event)")


